import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DpI_zlPE.js";var i=JSON.parse(`{"title":"影像兼容颜料墨水","description":"","frontmatter":{},"headers":[],"relativePath":"ccc/色彩管理/兼容影像颜料墨水.md","filePath":"ccc/色彩管理/兼容影像颜料墨水.md"}`),a={name:`ccc/色彩管理/兼容影像颜料墨水.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="影像兼容颜料墨水" tabindex="-1">影像兼容颜料墨水 <a class="header-anchor" href="#影像兼容颜料墨水" aria-label="Permalink to “影像兼容颜料墨水”">​</a></h1><h2 id="改颜料优选原装颜料机型" tabindex="-1">改颜料优选原装颜料机型 <a class="header-anchor" href="#改颜料优选原装颜料机型" aria-label="Permalink to “改颜料优选原装颜料机型”">​</a></h2><p>目前常用于改颜料的机型是爱普生L8058机型。据网友介绍，打印质量必须选高，选标准大概率出横纹。大面积堆墨，如蓝天往往可能出现缩孔现象露白，而一些润湿性相对更好的墨水，不露白但往往又干得太慢，会出现齿轮印。</p><p>我推测可能同L8058机型喷墨程序追求速度牺牲了质量有关。</p><p>同时爱普生打印头目前是压电薄膜而非以前的压电陶瓷，<strong>我猜测</strong>，喷墨波形的宽容度可能不如压电陶瓷，既可能对墨水性质的适应范围相对更窄，所以染料机型改颜料的稳定性可能不是最理想，或者说对商用而言不够稳定。</p><p>如果要用水性颜料墨水，优选原装就是用颜料墨水的机型，如P708、WF-4838、WF-7318、L15168等。</p><h2 id="兼容颜料特性" tabindex="-1">兼容颜料特性 <a class="header-anchor" href="#兼容颜料特性" aria-label="Permalink to “兼容颜料特性”">​</a></h2><p>1、黑灰墨水黑位不正，既爱普生原装黑灰墨水通常反射率光谱是直线，而兼容颜料，往往带点轻微的色度，通常泛红褐色，光谱反射率在660nm以上会翘曲。</p><blockquote><p>由于纸张本身往往带点色度，所以黑白打印，爱普生原装墨水也不是单纯只喷黑灰墨水，还是会稍微带点彩色墨点。</p><p>不清楚实际影响有多大，理论上黑白以外的场景，校色后应该没有特别大影响。</p></blockquote><p>2、黑色墨水黑位观感相对爱普生原装墨水有显著差距。</p><p>3、色密度相对原装墨水有差距，尤其是Y黄色。不过承载信息的是阶调而非饱和色域，实际影响可能没有数字表现得那么大。爱普生是靠鲜洋红色墨水扩展色域来实现不错的大红色，但兼容墨水会很尴尬，弄出来的大红色饱和度有差距。</p><p>4、黑色墨水反光泛白（烫金效应）特别严重，和其他颜色墨水反光的光感区别很大。爱普生原装墨水反光泛白比较自然，不同颜色墨水的整体光感相近。</p><p>5、兼容颜料墨水的成膜树脂本身往往泛点黄色，所以堆黑反光是黄色的，而爱普生原装墨水的堆黑反光通常泛白。</p><p>6、CMYK以外的专色如大红RED、蓝BLUE、绿GREEN、紫罗兰VIOLET等，较大概率是假把式，用CMYK勾兑，不扩展色域。</p><h3 id="最大短板" tabindex="-1">最大短板： <a class="header-anchor" href="#最大短板" aria-label="Permalink to “最大短板：”">​</a></h3><p>当下爱普生桌面机型都是ESC/PR协议，传输的是RGB数据，转换为实际喷墨墨点（RIP分色程序、喷墨程序）由打印机固件进行。</p><p>而通常进行的RGB校色只能改变传递给打印机的RGB值，是描述而非校准，既描述输出某个RGB值实际打印的色值。而兼容墨水由于不匹配打印程序，插值可靠度不如原装墨水，既同样校色的绝对色准，相对原装墨水有一点差距。</p><p>爱普生P708支持ESC/P2协议，可以直接控制墨点，开源驱动Gutenprint可以强行打印，但由于该驱动开发趋于停滞，所以没有适配爱普生P708，Violet没法分色也没法输出，粗面黑没法输出。要用的话，还要自己开发配置，但没有傻瓜教程，比如设置最大墨量，LC、LM、黑灰墨水的分色，CMYK线性化等，都没有现成的教程，甚至连能用的测试图都没有。开源驱动通常要多喷好几遍墨，花原厂驱动数倍时间进行喷墨才能取得更好的效果。</p><p>爱普生P7080等大幅面机型，买一个EFI Fiery的盗版USB加密狗，装EFI Fiery RIP的Halftone CMYK（半色调CMYK）驱动，有傻瓜流程进行最大墨量、CMYK线性化的配置。可以最大程度的发挥兼容墨水的性能。</p><h2 id="鸿盛鸿彩6" tabindex="-1">鸿盛鸿彩6 <a class="header-anchor" href="#鸿盛鸿彩6" aria-label="Permalink to “鸿盛鸿彩6”">​</a></h2><p><strong>务必审慎！务必审慎！务必审慎！</strong></p><p><strong>推测</strong>成膜树脂含量较高，可能有较大堵头风险。</p><p>在无反光的艺术纸上，鸿盛鸿彩6相对原装颜料墨水主要是色密度的差异。</p><p>主要观感差异在于光泽纸上。</p><p><strong>反光较显眼，尤其黑色墨水</strong>。</p><p>鸿盛鸿彩6颜料墨水的黑色墨水反光泛白的现象严重非常多，可能在爱普生原装颜料的黑墨上产生的反光，不是很显眼的位置，鸿盛可能就会感觉过于显眼。</p><p>鸿盛CMY墨水的反光观感一致，只会泛白，不会泛青铜色，避免了泛青铜色的诡异观感。而爱普生原装墨水不同颜色的墨水反光观感会有轻微差异。</p><p>我推测可能是鸿盛的成膜树脂形成的膜层相对较厚，可能对色密度有影响。</p><p><strong>鸿盛的色密度受限，黑位有明显差距</strong>。碳黑模式甚至是负作用。</p><p>碳黑模式既在黑色墨点附近喷LGY墨水，原装墨水用以增强色密度，减轻烫金效应的影响，但在鸿盛鸿彩6墨水上更厚的膜层反而导致观感上黑位更不黑，烫金效应愈发严重。由于鸿盛具有兼容墨水一贯的，黑灰墨水的黑位不正、成膜树脂发黄，碳黑模式启用与否应重新校色。</p><h3 id="cmy反光观感一致可能适合4-6色机型" tabindex="-1">CMY反光观感一致可能适合4~6色机型 <a class="header-anchor" href="#cmy反光观感一致可能适合4-6色机型" aria-label="Permalink to “CMY反光观感一致可能适合4~6色机型”">​</a></h3><p>通常4~6色机型的灰阶由CMY墨水混合而成，而CMY墨水的反光观感差异，是导致其灰阶反光观感诡异的重大来源。</p><p>基于鸿盛鸿彩6墨水表现出CMY反光观感相对一致的特性，<strong>我推测</strong>，可能在4~6色机型上，鸿盛鸿彩6可能可以避免灰阶反光观感诡异，更偏向单纯的反光泛白。</p><p>黑色墨水可能考虑爱普生原装颜料墨盒抽墨。</p><h3 id="风险巨大" tabindex="-1">风险巨大 <a class="header-anchor" href="#风险巨大" aria-label="Permalink to “风险巨大”">​</a></h3><p>从鸿盛墨水的表现，<strong>我猜测</strong>，可能成膜树脂含量占比相对较高，而颜料含量占比相对较低，<strong>堵头风险可能更大</strong>。</p><p>从爱普生P708上机鸿盛墨水的表现可见一斑，上机几个月打印头检查图就开始出状况，出现斜喷、卫星滴等异常现象，不过即使检查图异常，打照片一般没有可感知的瑕疵。即使多次清洗后打检查图正常了，也撑不了几天。</p><p>显然鸿盛鸿彩6，每周打一次的维护频率不够，应该说只适合工商业用户。据大幅面打印机服务商的市场人员介绍，其客户用鸿盛鸿彩6墨水居多，都感觉挺稳定的。</p><p>爱普生P708有气泵，鸿盛鸿彩6的稳定性就已经不太理想，如果要用在4~6色机型上，很可能是灾难。有多位网友反馈，鸿盛鸿彩6导致其4~6色机型打印头报废，拆下来看，打印头上都是絮状物。</p><p>桌面机型如果想上鸿盛鸿彩6水性颜料墨水，请务必审慎。 桌面机型如果想上鸿盛鸿彩6水性颜料墨水，请务必审慎。 桌面机型如果想上鸿盛鸿彩6水性颜料墨水，请务必审慎。</p>`,40)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};